parameters.functionScript:
/*
 * Ported from the Hub's ics-generator.js (legacy/hub/frontend/src/lib/ics-generator.js):
 * one VEVENT in UTC, reminders a day and 15 minutes before, the meeting link as the
 * location. No organiser line: who the coach is lives in the backend, never in the graph.
 * The file is built in the browser and handed over as a download; nothing is uploaded.
 */
const start = new Date(Inputs.startsAt);
if (isNaN(start)) return;
const minutes = Number(Inputs.durationMin) || 60;
const end = new Date(start.getTime() + minutes * 60000);
const stamp = (d) => d.toISOString().split('-').join('').split(':').join('').slice(0, 15) + 'Z';
const esc = (t) => String(t || '').split('\\').join('\\\\').split(';').join('\\;').split(',').join('\\,').split('\n').join('\\n');
const link = String(Inputs.meetingLink || '');
const lines = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//Digital Bricks University//Plan//EN',
  'CALSCALE:GREGORIAN',
  'METHOD:PUBLISH',
  'BEGIN:VEVENT',
  'UID:step-' + Inputs.stepId + '@digital-bricks-university',
  'DTSTAMP:' + stamp(new Date()),
  'DTSTART:' + stamp(start),
  'DTEND:' + stamp(end),
  'SUMMARY:' + esc(Inputs.title),
  'DESCRIPTION:' + esc([Inputs.details, link].filter(Boolean).join('\n')),
  link ? 'LOCATION:' + esc(link) : '',
  link ? 'URL:' + link : '',
  Inputs.attendeeEmail ? 'ATTENDEE;CN=' + esc(Inputs.attendeeName) + ':mailto:' + Inputs.attendeeEmail : '',
  'STATUS:CONFIRMED',
  'BEGIN:VALARM', 'ACTION:DISPLAY', 'DESCRIPTION:' + esc(Inputs.title), 'TRIGGER:-P1D', 'END:VALARM',
  'BEGIN:VALARM', 'ACTION:DISPLAY', 'DESCRIPTION:' + esc(Inputs.title), 'TRIGGER:-PT15M', 'END:VALARM',
  'END:VEVENT',
  'END:VCALENDAR'
].filter(Boolean);
const blob = new Blob([lines.join('\r\n')], { type: 'text/calendar;charset=utf-8' });
const url = URL.createObjectURL(blob);
const a = document.createElement('a');
a.href = url;
a.download = (String(Inputs.title || 'session').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean).join('-') || 'session') + '.ics';
document.body.appendChild(a);
a.click();
document.body.removeChild(a);
setTimeout(() => URL.revokeObjectURL(url), 1000);

// Google's 'add an event' address, as the Hub built it (generateGoogleCalendarURL).
const start = new Date(Inputs.startsAt);
if (isNaN(start)) return;
const end = new Date(start.getTime() + (Number(Inputs.durationMin) || 60) * 60000);
const g = (d) => d.toISOString().split('-').join('').split(':').join('').slice(0, 15) + 'Z';
const link = String(Inputs.meetingLink || '');
const params = new URLSearchParams({
  action: 'TEMPLATE',
  text: String(Inputs.title || ''),
  dates: g(start) + '/' + g(end),
  details: [Inputs.details, link].filter(Boolean).join('\n\n'),
  location: link
});
window.open('https://calendar.google.com/calendar/render?' + params.toString(), '_blank', 'noopener');
